// Source-only inventory. Exact global functions, including captured guards,
// may match across different lexical scopes; no fingerprint acceptance.
fn product_inventory(ops:&[Op])->serde_json::Value{
 let no=u64::MAX;let(nq,nb,_,_)=quantum_ecc::circuit::analyze_ops(ops.iter());let(nq,nb)=(nq as usize,nb as usize);let mut alg=Algebra{inner:Expr::default()};let(mut q,mut c)=initial_inputs(ops,nq,nb,&mut alg);let(mut base,mut stack)=(1,vec![]);let mut uses=HashMap::<u32,Vec<usize>>::new();let(mut zero_reset_events,mut native_ccx)=(0usize,0usize);
 for(i,o)in ops.iter().enumerate(){if o.kind==K::PushCondition{stack.push(base);base=alg.inner.and(base,c[o.c_condition.0 as usize]);continue;}if o.kind==K::PopCondition{base=stack.pop().unwrap();continue;}let g=if o.c_condition.0==no{base}else{alg.inner.and(base,c[o.c_condition.0 as usize])};let(t,a,b,ct)=(o.q_target.0 as usize,o.q_control1.0 as usize,o.q_control2.0 as usize,o.c_target.0 as usize);
  let toggle=match o.kind{K::X=>Some(g),K::CX=>Some(alg.inner.and(q[a],g)),K::CCX=>{native_ccx+=1;let ab=alg.inner.and(q[a],q[b]);let actual=alg.inner.and(g,ab);let f=ab;if f>1{uses.entry(f).or_default().push(i);}Some(actual)},_=>None};
  if matches!(o.kind,K::R|K::Hmr)&&alg.inner.and(g,q[t])==0{zero_reset_events+=1;}
  match o.kind{K::X|K::CX|K::CCX=>q[t]=alg.inner.xor(q[t],toggle.unwrap()),K::Swap=>{let v=alg.inner.xor(q[a],q[t]);let v=alg.inner.and(g,v);q[a]=alg.inner.xor(q[a],v);q[t]=alg.inner.xor(q[t],v);},K::R|K::Hmr=>{q[t]=alg.inner.and(q[t],g^1);if o.kind==K::Hmr{let r=alg.inner.atom();c[ct]=alg.inner.ite(g,r,c[ct]);}},K::BitInvert=>c[ct]=alg.inner.xor(c[ct],g),K::BitStore0=>c[ct]=alg.inner.and(c[ct],g^1),K::BitStore1=>c[ct]=alg.inner.or(c[ct],g),K::Neg|K::Z|K::CZ|K::CCZ|K::Register|K::AppendToRegister|K::DebugPrint=>{},_=>unreachable!()}
  if i%1000000==0{eprintln!("GLOBAL_PRODUCT_INVENTORY op={i} keys={} semantic_nodes={}",uses.len(),alg.inner.nodes.len());}
 }
 assert!(stack.is_empty());let mut groups:Vec<_>=uses.into_iter().filter(|(_,indices)|indices.len()>=2).collect();groups.sort_by_key(|(_,indices)|indices[0]);let pairs=groups.iter().filter(|(_,v)|v.len()==2).count();let triples=groups.iter().filter(|(_,v)|v.len()>=3).count();let occurrences:usize=groups.iter().map(|(_,v)|v.len()).sum();serde_json::json!({"status":"READ_ONLY_EXACT_GLOBAL_PRODUCT_REPETITION_INVENTORY_NOT_A_CIRCUIT_OR_SCORE","original_qubits":nq,"ccx_records":native_ccx,"repeated_function_groups":groups.len(),"pair_groups":pairs,"groups_with_at_least_three_uses":triples,"records_in_repeated_groups":occurrences,"source_zero_effect_reset_events":zero_reset_events,"groups":groups.iter().map(|(f,indices)|serde_json::json!({"global_function":f,"records":indices})).collect::<Vec<_>>(),"semantic_nodes":alg.inner.nodes.len(),"input_records_sha3":hash(ops),"scope":"RAW control product inventory on original full-prefix values, before original effective classical guard. Actual guarded quantum/classical replay unchanged. Repeated raw keys only nominate; a future guarded-cache proof must show each original effective toggle equals its original guard times the captured cache value. Lexicalscope identity and current guard deliberately excluded from raw key; captured predicate effects in quantum values remain exact. Inventory only. Possible exact no-new-RNG cache: >=3uses with unitary uncompute, or2uses with source-proved zero-effect existing measurement and exact phase repair. Neither transformation is implemented/qualified or scored here."})
}
#[cfg(test)]mod global_product_inventory_tests{use super::*;
 fn fixture()->Vec<Op>{let n=u64::MAX;let mut ops=vec![];for q in 0..4{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=quantum_ecc::circuit::RegisterId(0);o.q_target=QubitId(q);ops.push(o);}let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=quantum_ecc::circuit::RegisterId(1);o.c_target=BitId(0);ops.push(o);ops.extend([make(K::PushCondition,n,n,n,n,0),make(K::CCX,0,1,2,n,n),make(K::PopCondition,n,n,n,n,n),make(K::PushCondition,n,n,n,n,0),make(K::CCX,0,1,3,n,n),make(K::PopCondition,n,n,n,n,n)]);ops}
 #[test]fn identical_captured_predicate_across_sibling_scopes_is_one_exact_function(){let r=product_inventory(&fixture());assert_eq!(r["pair_groups"],1);assert_eq!(r["groups_with_at_least_three_uses"],0);}
 #[test]fn changed_guard_keeps_same_raw_product_but_not_effective_toggle(){let n=u64::MAX;for fresh in[false,true]{let mut ops=fixture();ops.insert(8,if fresh{make(K::Hmr,n,n,2,0,n)}else{make(K::BitInvert,n,n,n,0,n)});let r=product_inventory(&ops);assert_eq!(r["repeated_function_groups"],1);}}
 #[test]fn changed_quantum_control_changes_raw_product(){let n=u64::MAX;let mut ops=fixture();ops.insert(8,make(K::X,n,n,0,n,n));assert_eq!(product_inventory(&ops)["repeated_function_groups"],0);}

}
